// Generate SDK types from an explicitly selected OpenAPI document. The
// generated file is committed and builds do not depend on a live service.
//
// Override target spec via SKILLOS_OPENAPI_URL env var (for local API dev).
//
// CI emits the API spec locally and runs this command as a drift check.

import { writeFileSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import openapiTS, { astToString } from 'openapi-typescript';

const here = dirname(fileURLToPath(import.meta.url));
const OUT = resolve(here, '../src/api.gen.ts');
const SPEC_URL = process.env.SKILLOS_OPENAPI_URL;

async function main(): Promise<void> {
  if (!SPEC_URL) {
    throw new Error(
      'SKILLOS_OPENAPI_URL is required (use a local file:// spec or an explicit endpoint)',
    );
  }
  console.log(`[generate-types] fetching ${SPEC_URL}`);
  const ast = await openapiTS(new URL(SPEC_URL));
  const banner =
    '// AUTO-GENERATED by scripts/generate-types.ts — do not edit by hand.\n' +
    '// Source of truth: apps/api OpenAPI document emitted in CI\n' +
    '// Regenerate via: npm run generate-types\n\n';
  writeFileSync(OUT, banner + astToString(ast));
  console.log(`[generate-types] wrote ${OUT}`);
}

main().catch((err: unknown) => {
  console.error('[generate-types] FAIL:', err);
  process.exit(1);
});
